(() => {
  // Authored facial shapes from the original licensed VRM sources already
  // credited in assets/characters/LICENSES.txt: AvatarSample_C (Blink 11,
  // Fun 1) and Victoria_Rubin (Blink 12, Fun 1). Face vertex order was verified
  // identical to the shipped GLBs. Targets were passed through the v32 prince
  // and princess facial sculpts before packing at 2 micrometre precision.
  // Fun is the closed-mouth expression; the open-mouth Joy shape is unused.
  const AUTHORED = {"wsq":{"vertices":2056,"quantum":0.000002,"source":"AvatarSample_C","sculptVersion":"v32","targets":{"blink":"","fun":""}},"lyp":{"vertices":2339,"quantum":0.000002,"source":"Victoria_Rubin","sculptVersion":"v32","targets":{"blink":"","fun":""}}};
  const instances = new WeakMap();
  const clamp = (value, low = 0, high = 1) => Math.max(low, Math.min(high, Number.isFinite(value) ? value : 0));
  const smooth = (a, b, value) => { const t = clamp((value - a) / (b - a)); return t * t * (3 - 2 * t); };

  function decode(packed, vertices, quantum) {
    const bytes = Uint8Array.from(atob(packed), (character) => character.charCodeAt(0));
    const view = new DataView(bytes.buffer), output = new Float32Array(vertices * 3);
    for (let offset = 0; offset < bytes.length; offset += 8) {
      const index = view.getUint16(offset, true) * 3;
      for (let axis = 0; axis < 3; axis += 1) output[index + axis] = view.getInt16(offset + 2 + axis * 2, true) * quantum;
    }
    return output;
  }

  window.createJourneyExpression = ({ gltf, root = gltf?.scene, bones = {}, feminine = false } = {}) => {
    const T = window.THREE;
    if (!T || !root) return null;
    if (instances.has(root)) return instances.get(root);
    const data = AUTHORED[feminine ? 'lyp' : 'wsq'];
    const blink = decode(data.targets.blink, data.vertices, data.quantum);
    const fun = decode(data.targets.fun, data.vertices, data.quantum);
    const changes = [], geometries = new Set(), eyes = [];
    const previousTag = root.userData.journeyExpression;
    const stats = { source: `${data.source}: Blink + Fun`, sculptVersion: data.sculptVersion,
      blinkSupported: true, smile: 'authored-closed-mouth', meshes: 0, morphsPerMesh: 3, gazeBones: 0 };
    let disposed = false, lastBlink = -1, lastSmile = -1;
    const eyeRotation = new T.Quaternion(), eyeEuler = new T.Euler(0, 0, 0, 'YXZ');
    const meshes = [];
    root.traverse((mesh) => {
      if (!mesh.isSkinnedMesh || mesh.userData.journeyAnimeOutline) return;
      const names = (Array.isArray(mesh.material) ? mesh.material : [mesh.material]).map((material) => material.name || '');
      if (names.some((name) => /Face|Eye|Brow/.test(name)) && !names.some((name) => /HAIR|AnimeContour/.test(name))
        && mesh.geometry.attributes.position.count === data.vertices) meshes.push({ mesh, names });
    });
    if (!meshes.length) return null;

    // Locate the mouth in the current sculpt rather than using a sex-specific
    // screen-space mask. The thin eye/iris/lash layers use the same vertex IDs.
    const mouth = meshes.find(({ names }) => names.some((name) => /FaceMouth/.test(name)))?.mesh;
    let mouthLow = Infinity, mouthHigh = -Infinity;
    if (mouth) {
      const position = mouth.geometry.attributes.position;
      const indices = mouth.geometry.index?.array || Array.from({ length: position.count }, (_, i) => i);
      for (const index of indices) { mouthLow = Math.min(mouthLow, position.getY(index)); mouthHigh = Math.max(mouthHigh, position.getY(index)); }
    }
    const mouthY = Number.isFinite(mouthLow) ? (mouthLow + mouthHigh) / 2 : feminine ? 1.502 : 1.547;

    function normalDelta(geometry, delta) {
      const temporary = geometry.clone();
      const base = geometry.attributes.position;
      const target = new Float32Array(base.count * 3);
      for (let i = 0; i < base.count; i += 1) {
        target[i * 3] = base.getX(i) + delta[i * 3];
        target[i * 3 + 1] = base.getY(i) + delta[i * 3 + 1];
        target[i * 3 + 2] = base.getZ(i) + delta[i * 3 + 2];
      }
      temporary.setAttribute('position', new T.BufferAttribute(target, 3));
      temporary.computeVertexNormals();
      const before = geometry.attributes.normal, after = temporary.attributes.normal;
      const result = new Float32Array(target.length);
      for (let i = 0; i < before.count; i += 1) {
        const x = after.getX(i), y = after.getY(i), z = after.getZ(i);
        // Some authored eye surfaces collapse behind the lid at full close.
        // A finite fallback normal keeps those degenerate triangles harmless.
        if (x * x + y * y + z * z < .000001) continue;
        result[i * 3] = x - before.getX(i);
        result[i * 3 + 1] = y - before.getY(i);
        result[i * 3 + 2] = z - before.getZ(i);
      }
      temporary.dispose();
      return result;
    }

    function restore() {
      changes.forEach(({ mesh, geometry, influences, dictionary }) => {
        mesh.geometry = geometry;
        mesh.morphTargetInfluences = influences;
        mesh.morphTargetDictionary = dictionary;
      });
      eyes.forEach(({ bone, rest }) => { bone.quaternion.copy(rest); });
      geometries.forEach((geometry) => geometry.dispose());
      if (previousTag === undefined) delete root.userData.journeyExpression;
      else root.userData.journeyExpression = previousTag;
      instances.delete(root);
    }

    try {
      meshes.forEach(({ mesh, names }) => {
        if (mesh.geometry.morphAttributes.position?.length) return;
        const original = mesh.geometry, geometry = original.clone();
        geometries.add(geometry);
        if (!geometry.attributes.normal) geometry.computeVertexNormals();
        const upperLayer = names.some((name) => /Eye|Brow/.test(name));
        const lower = new Float32Array(fun.length), upper = new Float32Array(fun.length);
        for (let index = 0; index < data.vertices; index += 1) {
          const at = index * 3;
          const closesWithLid = Math.abs(blink[at]) + Math.abs(blink[at + 1]) + Math.abs(blink[at + 2]) > .000001;
          const share = upperLayer || closesWithLid ? 1 : smooth(mouthY + .018, mouthY + .031, geometry.attributes.position.getY(index));
          for (let axis = 0; axis < 3; axis += 1) {
            upper[at + axis] = fun[at + axis] * share;
            lower[at + axis] = fun[at + axis] * (1 - share);
          }
        }
        const targets = [blink, lower, upper], namesOfTargets = ['JourneyBlink', 'JourneySmile', 'JourneySmileEyes'];
        // Do not set the live morph attributes until all normal targets have
        // been derived from the same neutral geometry.
        const normals = targets.map((delta) => normalDelta(geometry, delta));
        geometry.morphTargetsRelative = true;
        geometry.morphAttributes.position = targets.map((delta, index) => {
          const attribute = new T.BufferAttribute(delta, 3); attribute.name = namesOfTargets[index]; return attribute;
        });
        geometry.morphAttributes.normal = normals.map((delta, index) => {
          const attribute = new T.BufferAttribute(delta, 3); attribute.name = namesOfTargets[index]; return attribute;
        });
        changes.push({ mesh, geometry: original, influences: mesh.morphTargetInfluences, dictionary: mesh.morphTargetDictionary });
        mesh.geometry = geometry;
        mesh.updateMorphTargets();
        stats.meshes += 1;
      });

      // The original iris primitives are genuinely weighted to these eye
      // bones. Native eye rotation avoids texture uploads or pupil sliding.
      const iris = meshes.find(({ names }) => names.some((name) => /EyeIris/.test(name)))?.mesh;
      const map = gltf.parser?.json?.asset?.extras?.humanoid || {};
      for (const key of ['leftEye', 'rightEye']) {
        const entry = map[key];
        const bone = bones[key] || (entry && root.getObjectByName(typeof entry === 'string' ? entry : entry.name));
        const boneIndex = iris?.skeleton.bones.indexOf(bone) ?? -1;
        const joints = iris?.geometry.attributes.skinIndex, weights = iris?.geometry.attributes.skinWeight;
        const indices = iris?.geometry.index?.array;
        let bound = false;
        if (bone && boneIndex >= 0 && joints && weights && indices) {
          const component = ['getX', 'getY', 'getZ', 'getW'];
          for (const index of indices) {
            for (let axis = 0; axis < 4; axis += 1) {
              if (joints[component[axis]](index) === boneIndex && weights[component[axis]](index) > .1) bound = true;
            }
            if (bound) break;
          }
        }
        if (bound) eyes.push({ bone, rest: bone.quaternion.clone() });
      }
      stats.gazeBones = eyes.length;
      root.userData.journeyExpression = { ...stats };
    } catch (error) { restore(); throw error; }

    const api = {
      stats,
      update({ blink = 0, smile = 0, lookX = 0, lookY = 0 } = {}) {
        if (disposed) return;
        const close = clamp(blink), warmth = clamp(smile);
        if (close !== lastBlink || warmth !== lastSmile) {
          changes.forEach(({ mesh }) => {
            mesh.morphTargetInfluences[0] = close;
            mesh.morphTargetInfluences[1] = warmth;
            // Full blink always wins in the eye region; a smile cannot pull
            // one eyelid away from the other while the mouth keeps smiling.
            mesh.morphTargetInfluences[2] = warmth * (1 - close) * (1 - close);
          });
          lastBlink = close; lastSmile = warmth;
        }
        const focus = (1 - close) * (1 - close);
        eyeEuler.set(clamp(lookY, -1, 1) * .11 * focus, -clamp(lookX, -1, 1) * .18 * focus, 0, 'YXZ');
        eyeRotation.setFromEuler(eyeEuler);
        eyes.forEach(({ bone, rest }) => { bone.quaternion.copy(rest).multiply(eyeRotation); });
      },
      dispose() { if (!disposed) { disposed = true; restore(); } }
    };
    instances.set(root, api);
    api.update();
    return api;
  };
})();
